using namespace powder;
void check(bool b,const char* s){if(!b)throw std::runtime_error(s);}
void near(double a,double b,double tolerance,const char* s){check(std::abs(a-b)<=tolerance,s);}
template<class F>void rejects(F f,const char* s){bool rejected=false;try{f();}catch(const std::invalid_argument&){rejected=true;}check(rejected,s);}
Particle particle(Vec3 pos,double diameter=1){Particle p;p.id=1;p.position_m=pos;p.diameter_m=diameter;p.material.density_kg_m3=6/(3.14159265358979323846*diameter*diameter*diameter);return p;}
MeshInput grid(int n){MeshInput m;m.minimum_diagonal_m=5;m.maximum_diagonal_m=6;for(int y=0;y<=n;++y)for(int x=0;x<=n;++x)m.vertices.push_back({-2.+4.*x/n,-2.+4.*y/n,0});for(int y=0;y<n;++y)for(int x=0;x<n;++x){auto a=static_cast<std::size_t>(y*(n+1)+x),b=a+1,c=a+n+1,d=c+1;m.triangles.push_back({a,b,d});m.triangles.push_back({a,d,c});}for(int k=0;k<n;++k){auto i=static_cast<std::size_t>(k),w=static_cast<std::size_t>(n+1);m.boundaries.push_back({{i,i+1},BoundaryKind::Perimeter});m.boundaries.push_back({{n*w+i,n*w+i+1},BoundaryKind::Perimeter});m.boundaries.push_back({{i*w,(i+1)*w},BoundaryKind::Perimeter});m.boundaries.push_back({{i*w+n,(i+1)*w+n},BoundaryKind::Perimeter});}return m;}
MeshInput tube(){MeshInput m;m.minimum_diagonal_m=1;m.maximum_diagonal_m=2;for(double z:{0.,1.})for(Vec3 v:std::vector<Vec3>{{-.1,-.1,z},{.1,-.1,z},{.1,.1,z},{-.1,.1,z}})m.vertices.push_back(v);for(std::size_t i=0;i<4;++i){auto j=(i+1)%4;m.triangles.push_back({i,j,j+4});m.triangles.push_back({i,j+4,i+4});m.boundaries.push_back({{i,j},BoundaryKind::Outlet});m.boundaries.push_back({{i+4,j+4},BoundaryKind::Inlet});}return m;}
int main(){try{
 FixedBox box;box.id=1;box.half_m={1,1,1};StaticTriangleMesh cube(triangulated_box(box));
 for(int k=1;k<=3;++k){auto p=particle({1.2,k>=2?1.2:0,k>=3?1.2:0});auto a=box_contacts(p,{box});auto b=cube.query(p).contacts;check(b.size()==1,"convex face/edge/vertex one force");near(a[0].overlap_m,b[0].overlap_m,1e-12,"mesh/box overlap");near(a[0].normal.x,b[0].normal.x,1e-12,"mesh/box normal");}
 rejects([&]{cube.query(particle({0,0,0}));},"closed solid initial interior rejected");
 auto rotated=box;double c=std::sqrt(.5);rotated.axes={Vec3{c,c,0},Vec3{-c,c,0},Vec3{0,0,1}};rotated.centre_m={4,5,6};rotated.half_m={2,1,.5};StaticTriangleMesh rotated_mesh(triangulated_box(rotated));auto p=particle({4+2.2*c,5+2.2*c,6});near(rotated_mesh.query(p).contacts[0].overlap_m,box_contacts(p,{rotated})[0].overlap_m,1e-12,"transformed mesh matches box");
 auto cm=triangulated_box(box);for(auto& v:cm.vertices){v.x*=100;v.y*=100;v.z*=100;}cm.metres_per_unit=.01;StaticTriangleMesh scaled(cm);near(scaled.query(particle({1.2,0,0})).contacts[0].overlap_m,.3,1e-12,"explicit cm conversion");cm.metres_per_unit=1;rejects([&]{StaticTriangleMesh wrong(cm);},"unit mistake detected by independent size contract");
 auto bad=grid(1);bad.triangles.push_back(bad.triangles[0]);rejects([&]{StaticTriangleMesh a(bad);},"duplicate face rejected");bad=grid(1);std::swap(bad.triangles[1][0],bad.triangles[1][1]);rejects([&]{StaticTriangleMesh a(bad);},"inconsistent winding rejected");bad=grid(1);bad.triangles[0][1]=bad.triangles[0][0];rejects([&]{StaticTriangleMesh a(bad);},"degenerate triangle rejected");bad=grid(1);bad.boundaries.pop_back();rejects([&]{StaticTriangleMesh a(bad);},"unintended gap not silently treated as port");bad=grid(1);bad.vertices.push_back({0,0,1});bad.triangles.push_back({0,3,4});rejects([&]{StaticTriangleMesh a(bad);},"nonmanifold edge rejected");
 StaticTriangleMesh sheet(grid(16));check(sheet.diagnostics().patches==1,"coplanar topology welded");std::uint64_t key=0;std::size_t checks=0;for(int i=0;i<=400;++i){auto q=particle({-1.5+.0075*i,.123,.499});auto a=sheet.query(q),b=sheet.query(q,true);check(a.contacts.size()==1&&b.contacts.size()==1,"no seam double forces or lost contacts");near(a.contacts[0].normal.x,0,1e-12,"no artificial seam sideways force");near(a.contacts[0].overlap_m,b.contacts[0].overlap_m,1e-12,"BVH agrees with brute force");if(i==0)key=a.contacts[0].feature_id;check(a.contacts[0].feature_id==key,"friction history survives mesh seam");checks+=a.triangle_checks;}check(checks<401*512/3,"BVH prunes triangle checks");
 near(sheet.query(particle({0,0,-.499})).contacts[0].normal.z,-1,1e-12,"thin sheet two sided");rejects([&]{sheet.guard_motion({0,0,.001},{0,0,-.001});},"thin wall crossing caught");
 std::istringstream input(sheet.serialize());StaticTriangleMesh restored(read_triangle_mesh(input));check(restored.serialize()==sheet.serialize(),"SI geometry roundtrip exact");std::istringstream broken("POWDER_TRIANGLES 1");rejects([&]{read_triangle_mesh(broken);},"truncated mesh rejected");
 ParticleSystem meshed,plane;meshed.model.law=plane.model.law=ContactLaw::Linear;meshed.meshes={sheet};plane.planes={{1,{0,0,1},0}};meshed.particles={particle({-.15,0,.499})};meshed.particles[0].velocity_m_s.x=1;plane.particles=meshed.particles;
 for(int i=0;i<10000;++i){meshed.step(2e-5);plane.step(2e-5);}check(meshed.particles[0].position_m.x>0,"dynamic sliding crosses triangulation seams");double max_error=0;for(auto member:{&Vec3::x,&Vec3::y,&Vec3::z}){max_error=std::max(max_error,std::abs(meshed.particles[0].position_m.*member-plane.particles[0].position_m.*member));near(meshed.particles[0].position_m.*member,plane.particles[0].position_m.*member,1e-10,"mesh/plane trajectory");near(meshed.particles[0].angular_velocity_rad_s.*member,plane.particles[0].angular_velocity_rad_s.*member,1e-10,"mesh/plane friction spin");}
 ParticleSystem tunnel;tunnel.gravity_m_s2={};tunnel.model.law=ContactLaw::Linear;tunnel.model.linear={1,0,1,0,0};tunnel.meshes={sheet};tunnel.particles={particle({0,0,1e-5},.04)};tunnel.particles[0].velocity_m_s.z=-20;rejects([&]{tunnel.step(1e-6);},"thin wall step crossing is atomic error");near(tunnel.particles[0].position_m.z,1e-5,0,"failed crossing preserves state");check(tunnel.active_wall_histories()==0,"failed crossing preserves history");
 StaticTriangleMesh pipe(tube());check(pipe.diagnostics().inlet_edges==4&&pipe.diagnostics().outlet_edges==4,"explicit inlet/outlet classification");for(int i=0;i<=120;++i)check(pipe.query(particle({0,0,-.1+.01*i},.04)).contacts.empty(),"intended through path open");for(int i=0;i<=100;++i)check(!pipe.query(particle({.09,0,.01+.0098*i},.04)).contacts.empty(),"tube wall seam no gaps");check(pipe.query(particle({.09,.09,.5},.04)).contacts.size()==2,"real concave corner retains both constraints");pipe.guard_motion({0,0,1.1},{0,0,-.1});
 auto leaky=tube();leaky.triangles.pop_back();rejects([&]{StaticTriangleMesh leak(leaky);},"removed tube face is unintended leak");
 ParticleSystem fall;fall.meshes={pipe};fall.model.law=ContactLaw::Linear;fall.model.linear={10000,8,2500,2,.4};fall.particles={particle({0,0,1.01},.04)};fall.particles[0].velocity_m_s.z=-2;for(int i=0;i<30000;++i)fall.step(1e-5);check(fall.particles[0].position_m.z<0,"physical sphere passes inlet and outlet");
 auto analytic=clump_demo(),meshworld=analytic;analytic.bodies.resize(2);analytic.bodies[0].position_m={-.1,0,.024};analytic.bodies[1].position_m={.1,0,.04};for(auto& body:analytic.bodies)body.velocity_m_s.z=-.5;meshworld=analytic;meshworld.meshes.emplace_back(triangulated_box(meshworld.boxes[0]));meshworld.boxes.clear();double clump_error=0;std::size_t hits=0;for(int i=0;i<25000;++i){analytic.step(2e-6);hits+=meshworld.step(2e-6).wall_contacts;for(std::size_t j=0;j<2;++j){double e=std::abs(analytic.bodies[j].position_m.z-meshworld.bodies[j].position_m.z);clump_error=std::max(clump_error,e);}}check(hits>0,"clumps actually contact triangle mesh");check(clump_error<1e-10,"rigid clump mesh vs box trajectory");check(meshworld.bodies[0].position_m.z>0&&meshworld.bodies[1].position_m.z>0,"clumps do not leak through mesh floor");
 ParticleSystem hz;hz.model.law=ContactLaw::HertzMindlin;hz.gravity_m_s2={};hz.meshes={cube};hz.particles={particle({1.4999,0,0})};check(hz.step(1e-7).wall_contacts==1&&hz.particles[0].velocity_m_s.x>0,"Hertz mesh contact");
 // Same wall model, including rolling history and adhesion, across a welded plane.
 for(auto law:{ContactLaw::Linear,ContactLaw::HertzMindlin}){
  ParticleSystem a,b;a.model.law=b.model.law=law;a.model.adhesion_gamma_j_m2=b.model.adhesion_gamma_j_m2=.1;a.model.rolling=b.model.rolling={2000,3,.1};a.meshes={sheet};b.planes={{1,{0,0,1},0}};a.particles={particle({.001,0,.4999})};a.particles[0].velocity_m_s.x=.1;a.particles[0].angular_velocity_rad_s.y=1;b.particles=a.particles;
  for(int step=0;step<100;++step){a.step(1e-7);b.step(1e-7);}near(a.particles[0].velocity_m_s.x,b.particles[0].velocity_m_s.x,1e-12,"mesh rolling/adhesion tangent equivalence");near(a.particles[0].velocity_m_s.z,b.particles[0].velocity_m_s.z,1e-12,"mesh adhesive normal equivalence");near(a.particles[0].angular_velocity_rad_s.y,b.particles[0].angular_velocity_rad_s.y,1e-12,"mesh rolling torque equivalence");
 }
 FixedBox thin=box;thin.half_m.z=1e-5;StaticTriangleMesh thinmesh(triangulated_box(thin));for(double sign:{-1.,1.}){auto q=particle({0,0,sign*.01},.04);auto h=thinmesh.query(q).contacts;check(h.size()==1,"thin solid no opposite face double force");near(h[0].overlap_m,box_contacts(q,{thin})[0].overlap_m,1e-12,"thin solid matches analytic wall");}
 rejects([&]{thinmesh.guard_motion({0,0,.01},{0,0,-.01});},"thin solid crossing caught");
 std::cout<<"PASS static triangle mesh: face/edge/vertex, transformed box equivalence, units/topology/ports, thin wall atomic guard, BVH, seams and clumps\nplane_max_position_error_m="<<max_error<<"\nclump_max_z_error_m="<<clump_error<<"\ntriangle_checks="<<checks<<" / brute="<<401*512<<"\npipe_final_z_m="<<fall.particles[0].position_m.z<<"\n";return 0;
 }catch(const std::exception& e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}}
